// SPDX-License-Identifier: GPL-3.0-or-later
// Masked colour clear (declarations in nvn_mask_clear.h): one layout with a fragment push constant range, one pipeline per
// (format, attachment count, attachment, mask, kind, sample count) built with dynamic rendering. The shaders are in
// mask_clear_shaders.inc (generated by scripts/gen_mask_clear_shaders.py).
#include "nvn_mask_clear.h"

#include <algorithm>
#include <cstring>

#include "nxrt/log.h"

namespace nxrt::nvn::be {
namespace {
constexpr const char* kTag = "mask_clear";

struct ShaderBlob {
    const uint32_t* words;
    size_t bytes;
};

#include "mask_clear_shaders.inc"

}  // namespace

bool MaskClear::init(gfx::Device& dev) {
    if (dev_) return true;
    dev_ = &dev;
    VkDevice d = dev.device();
    auto fail = [&](const char* what) {
        NXLOG_E(kTag, "%s failed", what);
        shutdown();
        return false;
    };

    auto make_module = [&](const ShaderBlob& blob, VkShaderModule* out) {
        VkShaderModuleCreateInfo mi = {VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO};
        mi.codeSize = blob.bytes;
        mi.pCode = blob.words;
        return vkCreateShaderModule(d, &mi, nullptr, out) == VK_SUCCESS;
    };
    if (!make_module(kMaskClearVertBlob, &vert_)) return fail("vertex shader module");
    for (uint32_t k = 0; k < 3; ++k)
        for (uint32_t l = 0; l < kMaxAttachments; ++l)
            if (!make_module(kMaskClearFrag[k][l], &frag_[k][l])) return fail("fragment shader module");

    VkPushConstantRange pcr = {VK_SHADER_STAGE_FRAGMENT_BIT, 0, kPushBytes};
    VkPipelineLayoutCreateInfo pli = {VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO};
    pli.pushConstantRangeCount = 1;
    pli.pPushConstantRanges = &pcr;
    if (vkCreatePipelineLayout(d, &pli, nullptr, &layout_) != VK_SUCCESS) return fail("pipeline layout");
    return true;
}

void MaskClear::shutdown() {
    if (!dev_) return;
    VkDevice d = dev_->device();
    dev_->wait_idle();
    for (auto& kv : pipelines_)
        if (kv.second) vkDestroyPipeline(d, kv.second, nullptr);
    pipelines_.clear();
    if (layout_) vkDestroyPipelineLayout(d, layout_, nullptr);
    for (auto& row : frag_)
        for (auto& m : row)
            if (m) vkDestroyShaderModule(d, m, nullptr);
    if (vert_) vkDestroyShaderModule(d, vert_, nullptr);
    layout_ = VK_NULL_HANDLE;
    vert_ = VK_NULL_HANDLE;
    for (auto& row : frag_)
        for (auto& m : row) m = VK_NULL_HANDLE;
    dev_ = nullptr;
}

VkPipeline MaskClear::pipeline_for(const Key& key) {
    auto it = pipelines_.find(key);
    if (it != pipelines_.end()) return it->second;

    const auto format = static_cast<VkFormat>(std::get<0>(key));
    const uint32_t count = std::get<1>(key), index = std::get<2>(key), mask = std::get<3>(key), kind = std::get<4>(key);
    const auto samples = static_cast<VkSampleCountFlagBits>(std::get<5>(key));
    VkDevice d = dev_->device();

    VkPipelineShaderStageCreateInfo stages[2] = {{VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO}, {VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO}};
    stages[0].stage = VK_SHADER_STAGE_VERTEX_BIT;
    stages[0].module = vert_;
    stages[0].pName = "main";
    stages[1].stage = VK_SHADER_STAGE_FRAGMENT_BIT;
    stages[1].module = frag_[kind][index];
    stages[1].pName = "main";

    VkPipelineVertexInputStateCreateInfo vi = {VK_STRUCTURE_TYPE_PIPELINE_VERTEX_INPUT_STATE_CREATE_INFO};
    VkPipelineInputAssemblyStateCreateInfo ia = {VK_STRUCTURE_TYPE_PIPELINE_INPUT_ASSEMBLY_STATE_CREATE_INFO};
    ia.topology = VK_PRIMITIVE_TOPOLOGY_TRIANGLE_LIST;
    VkPipelineViewportStateCreateInfo vp = {VK_STRUCTURE_TYPE_PIPELINE_VIEWPORT_STATE_CREATE_INFO};
    vp.viewportCount = vp.scissorCount = 1;
    VkPipelineRasterizationStateCreateInfo rs = {VK_STRUCTURE_TYPE_PIPELINE_RASTERIZATION_STATE_CREATE_INFO};
    rs.polygonMode = VK_POLYGON_MODE_FILL;
    rs.cullMode = VK_CULL_MODE_NONE;
    rs.frontFace = VK_FRONT_FACE_COUNTER_CLOCKWISE;
    rs.lineWidth = 1.0f;
    VkPipelineMultisampleStateCreateInfo ms = {VK_STRUCTURE_TYPE_PIPELINE_MULTISAMPLE_STATE_CREATE_INFO};
    ms.rasterizationSamples = samples;

    // The NVN mask is the VkColorComponentFlags bit layout (R = 1, G = 2, B = 4, A = 8). Only the attachment being cleared gets it.
    VkPipelineColorBlendAttachmentState cba[kMaxAttachments] = {};
    for (uint32_t i = 0; i < count; ++i) cba[i].colorWriteMask = (i == index) ? mask : 0;
    VkPipelineColorBlendStateCreateInfo cb = {VK_STRUCTURE_TYPE_PIPELINE_COLOR_BLEND_STATE_CREATE_INFO};
    cb.attachmentCount = count;
    cb.pAttachments = cba;

    const VkDynamicState dyn[] = {VK_DYNAMIC_STATE_VIEWPORT, VK_DYNAMIC_STATE_SCISSOR};
    VkPipelineDynamicStateCreateInfo ds = {VK_STRUCTURE_TYPE_PIPELINE_DYNAMIC_STATE_CREATE_INFO};
    ds.dynamicStateCount = 2;
    ds.pDynamicStates = dyn;

    // Every colour attachment of the pass carries `format`. UNDEFINED entries would be legal only with the
    // dynamicRenderingUnusedAttachments feature, which the device does not enable: VUID-vkCmdDraw-dynamicRenderingUnusedAttachments-08910.
    VkFormat formats[kMaxAttachments];
    for (uint32_t i = 0; i < count; ++i) formats[i] = format;
    VkPipelineRenderingCreateInfo pri = {VK_STRUCTURE_TYPE_PIPELINE_RENDERING_CREATE_INFO};
    pri.colorAttachmentCount = count;
    pri.pColorAttachmentFormats = formats;

    VkGraphicsPipelineCreateInfo gpi = {VK_STRUCTURE_TYPE_GRAPHICS_PIPELINE_CREATE_INFO, &pri};
    gpi.stageCount = 2;
    gpi.pStages = stages;
    gpi.pVertexInputState = &vi;
    gpi.pInputAssemblyState = &ia;
    gpi.pViewportState = &vp;
    gpi.pRasterizationState = &rs;
    gpi.pMultisampleState = &ms;
    gpi.pColorBlendState = &cb;
    gpi.pDynamicState = &ds;
    gpi.layout = layout_;
    VkPipeline pipe = VK_NULL_HANDLE;
    if (vkCreateGraphicsPipelines(d, VK_NULL_HANDLE, 1, &gpi, nullptr, &pipe) != VK_SUCCESS) {
        NXLOG_E(kTag, "graphics pipeline failed (format %d, %u/%u attachments, mask 0x%x, kind %u)", static_cast<int>(format), index, count,
                mask, kind);
        return VK_NULL_HANDLE;
    }
    pipelines_.emplace(key, pipe);
    return pipe;
}

bool MaskClear::record(VkCommandBuffer cb, VkFormat color_format, uint32_t total_attachments, uint32_t attachment, uint32_t mask,
                       uint32_t kind, const uint32_t value[4], VkRect2D rect, uint32_t sample_count) {
    if (!dev_) return false;
    if (total_attachments == 0 || total_attachments > kMaxAttachments || attachment >= total_attachments || kind > 2) return false;
    if (sample_count == 0 || (sample_count & (sample_count - 1)) != 0 || sample_count > 64) return false;
    mask &= 0xF;
    if (mask == 0) return true;

    // The rectangle as the scissor and viewport need it: non-negative origin, clipped at the origin.
    const int32_t x0 = std::max(rect.offset.x, 0), y0 = std::max(rect.offset.y, 0);
    const int64_t x1 = static_cast<int64_t>(rect.offset.x) + rect.extent.width, y1 = static_cast<int64_t>(rect.offset.y) + rect.extent.height;
    if (x1 <= x0 || y1 <= y0) return true;
    const uint32_t w = static_cast<uint32_t>(x1 - x0), h = static_cast<uint32_t>(y1 - y0);

    const VkPipeline pipe = pipeline_for(Key{static_cast<int>(color_format), total_attachments, attachment, mask, kind, sample_count});
    if (!pipe) return false;

    // 32 bytes of push constants: the colour, then zeros (the shaders read the first 16).
    uint32_t pc[kPushBytes / 4] = {};
    std::memcpy(pc, value, 16);

    const VkViewport vpt = {static_cast<float>(x0), static_cast<float>(y0), static_cast<float>(w), static_cast<float>(h), 0.0f, 1.0f};
    const VkRect2D scissor = {{x0, y0}, {w, h}};
    vkCmdBindPipeline(cb, VK_PIPELINE_BIND_POINT_GRAPHICS, pipe);
    vkCmdSetViewport(cb, 0, 1, &vpt);
    vkCmdSetScissor(cb, 0, 1, &scissor);
    vkCmdPushConstants(cb, layout_, VK_SHADER_STAGE_FRAGMENT_BIT, 0, kPushBytes, pc);
    vkCmdDraw(cb, 3, 1, 0, 0);
    return true;
}

}  // namespace nxrt::nvn::be
